def gen(rng):
    QMAX = 10**15

    def divisors(x):
        r = []
        i = 1
        while i * i <= x:
            if x % i == 0:
                r.append(i)
                if i * i != x:
                    r.append(x // i)
            i += 1
        return r

    def case(N, C, Q, qmax):
        base = divisors(N)
        arr = sorted(set(base + [d * C for d in base]))
        lines = []
        for _ in range(Q):
            t = rng.random()
            if t < 0.35:
                d = rng.choice(arr)
                if d > qmax:
                    d = arr[0]
                a = max(1, d - rng.randint(0, 3))
                b = min(qmax, d + rng.randint(0, 3))
            elif t < 0.65 and len(arr) > 1:
                k = rng.randrange(len(arr) - 1)
                a, b = arr[k] + 1, arr[k + 1] - 1
                if a > b or b > qmax:
                    a = rng.randint(1, qmax)
                    b = min(qmax, a + rng.randint(0, 5))
            else:
                a = rng.randint(1, qmax)
                width = min(qmax - a, int(10 ** rng.uniform(0, 15)))
                b = a + rng.randint(0, width)
            lines.append('%d %d' % (a, b))
        return '%d %d %d\n' % (N, C, Q) + '\n'.join(lines)

    tests = ['1 2 3\n1 1\n2 2\n3 100', '1 2 2\n1 1\n3 5', '12 5 2\n7 9\n31 60', '1 2 1\n2 2']
    for _ in range(14):
        N = rng.randint(1, 30)
        C = rng.choice((2, 3, 5, 7, 11, 13))
        tests.append(case(N, C, rng.randint(1, 8), 200))
    for _ in range(4):
        N = rng.randint(1, 10**9)
        C = rng.choice((2, 3, 97, 999983))
        tests.append(case(N, C, 3000, QMAX))
    tests.append(case(735134400, 999983, 60000, QMAX))
    tests.append(case(735134400, 2, 60000, QMAX))
    tests.append(case(999999937, 999983, 60000, QMAX))
    tests.append(case(536870912, 2, 60000, QMAX))
    return tests

