import java.util.*;
import java.io.*;

public class Main {
    static String[] solve(long n, long c, long[][] queries) {
        // Write your solution here
        String[] res = new String[queries.length];
        Arrays.fill(res, "NO");
        return res;
    }

    public static void main(String[] args) throws IOException {
        StreamTokenizer in = new StreamTokenizer(new BufferedReader(new InputStreamReader(System.in)));
        in.nextToken();
        long n = (long) in.nval;
        in.nextToken();
        long c = (long) in.nval;
        in.nextToken();
        int q = (int) in.nval;
        long[][] queries = new long[q][2];
        for (int i = 0; i < q; i++) {
            in.nextToken(); queries[i][0] = (long) in.nval;
            in.nextToken(); queries[i][1] = (long) in.nval;
        }
        String[] res = solve(n, c, queries);
        StringBuilder sb = new StringBuilder();
        for (String s : res) sb.append(s).append("\n");
        System.out.print(sb);
    }
}
